450   * as well as set that we want the cert from the object.
   451   */
   452  static int cac_read_binary(sc_card_t *card, unsigned int idx,
   453                  unsigned char *buf, size_t count, unsigned long flags)
   454  {
   455          cac_private_data_t * priv = CAC_DATA(card);
   456          int r = 0;
   457          u8 *tl = NULL, *val = NULL;
   458          const u8 *tl_ptr, *val_ptr, *tl_start;
   459          u8 *tlv_ptr;
   460          const u8 *cert_ptr;
   461          size_t tl_len, val_len, tlv_len;
   462          size_t len, tl_head_len, cert_len;
   463          u8 cert_type, tag;
   464
   465          SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
   466
   467          /* if we didn't return it all last time, return the remainder */
   468          if (priv->cached) {
   469                  sc_log(card->ctx,
   470                           "returning cached value idx=%d count=%"SC_FORMAT_LEN_SIZE_T"u",
   471                           idx, count);
   472                  if (idx > priv->cache_buf_len) {
   473                          LOG_FUNC_RETURN(card->ctx, SC_ERROR_FILE_END_REACHED);
   474                  }
   475                  len = MIN(count, priv->cache_buf_len-idx);
   476                  memcpy(buf, &priv->cache_buf[idx], len);
   477                  LOG_FUNC_RETURN(card->ctx, len);
   478          }
   479
   480          sc_log(card->ctx,
   481                   "clearing cache idx=%d count=%"SC_FORMAT_LEN_SIZE_T"u",
   482                   idx, count);
   483          if (priv->cache_buf) {
   484                  free(priv->cache_buf);
   485                  priv->cache_buf = NULL;
   486                  priv->cache_buf_len = 0;
   487          }
   488
   489
   490          if (priv->object_type <= 0)
   491                   LOG_FUNC_RETURN(card->ctx, SC_ERROR_INTERNAL);
   492
   493          r = cac_read_file(card, CAC_FILE_TAG, &tl, &tl_len);
   494          if (r < 0)  {
   495                  goto done;
   496          }
   497
   498          r = cac_read_file(card, CAC_FILE_VALUE, &val, &val_len);
   499          if (r < 0)
   500                  goto done;
   501
   502          switch (priv->object_type) {
   503          case CAC_OBJECT_TYPE_TLV_FILE:
   504                  tlv_len = tl_len + val_len;
   505                  priv->cache_buf = malloc(tlv_len);
   506                  if (priv->cache_buf == NULL) {
   507                          r = SC_ERROR_OUT_OF_MEMORY;
   508                          goto done;
   509                  }
   510                  priv->cache_buf_len = tlv_len;
   511
   512                  for (tl_ptr = tl, val_ptr=val, tlv_ptr = priv->cache_buf;
   513                                  tl_len >= 2 && tlv_len > 0;
   514                                  val_len -= len, tlv_len -= len, val_ptr += len, tlv_ptr += len) {
   515                          /* get the tag and the length */
   516                          tl_start = tl_ptr;
   517                          r = sc_simpletlv_read_tag(&tl_ptr, tl_len, &tag, &len);
   518                          if (r != SC_SUCCESS && r != SC_ERROR_TLV_END_OF_CONTENTS)
   519                                  break;
   520                          tl_head_len = (tl_ptr - tl_start);
   521                          sc_simpletlv_put_tag(tag, len, tlv_ptr, tlv_len, &tlv_ptr);
   522                          tlv_len -= tl_head_len;
   523                          tl_len -= tl_head_len;
   524
   525                          /* don't crash on bad data */
   526                          if (val_len < len) {
   527                                  sc_log(card->ctx, "Received too long value %"SC_FORMAT_LEN_SIZE_T"u, "
   528                                      "while only %"SC_FORMAT_LEN_SIZE_T"u left. Truncating", len, val_len);
   529                                  len = val_len;
   530                          }
   531                          /* if we run out of return space, truncate */
   532                          if (tlv_len < len) {
   533                                  len = tlv_len;
   534                          }
   535                          memcpy(tlv_ptr, val_ptr, len);
   536                  }
   537                  break;
   538
   539          case CAC_OBJECT_TYPE_CERT:
   540                  /* read file */
   541                  sc_log(card->ctx,
   542                           " obj= cert_file, val_len=%"SC_FORMAT_LEN_SIZE_T"u (0x%04"SC_FORMAT_LEN_SIZE_T"x)",
   543                           val_len, val_len);
   544                  cert_len = 0;
   545                  cert_ptr = NULL;
   546                  cert_type = 0;
   547                  for (tl_ptr = tl, val_ptr = val; tl_len >= 2;
   548                      val_len -= len, val_ptr += len, tl_len -= tl_head_len) {
   549                          tl_start = tl_ptr;
   550                          r = sc_simpletlv_read_tag(&tl_ptr, tl_len, &tag, &len);
   551                          if (r != SC_SUCCESS && r != SC_ERROR_TLV_END_OF_CONTENTS)
   552                                  break;
   553                          tl_head_len = tl_ptr - tl_start;
   554
   555                          /* incomplete value */
   556                          if (val_len < len) {
   557                                  sc_log(card->ctx, "Read incomplete value %"SC_FORMAT_LEN_SIZE_T"u, "
   558                                      "while only %"SC_FORMAT_LEN_SIZE_T"u left", len, val_len);
   559                                  break;
   560                          }
   561
   562                          if (tag == CAC_TAG_CERTIFICATE) {
   563                                  cert_len = len;
   564                                  cert_ptr = val_ptr;
   565                          }
   566                          if (tag == CAC_TAG_CERTINFO) {
   567                                  if ((len >= 1) && (val_len >=1)) {
   568                                          cert_type = *val_ptr;
   569                                  }
   570                          }
   571                          if (tag == CAC_TAG_MSCUID) {
   572                                  sc_log_hex(card->ctx, "MSCUID", val_ptr, len);
   573                          }
   574                  }
   575                  /* if the info byte is 1, then the cert is compressed, decompress it */
   576                  if ((cert_type & 0x3) == 1) {
   577  #ifdef ENABLE_ZLIB
   578                          r = sc_decompress_alloc(&priv->cache_buf, &priv->cache_buf_len,
   579                                  cert_ptr, cert_len, COMPRESSION_AUTO);
   580  #else
   581                          sc_log(card->ctx, "CAC compression not supported, no zlib");
   582                          r = SC_ERROR_NOT_SUPPORTED;
   583  #endif
   584                          if (r)
   585                                  goto done;
   586                  } else if (cert_len > 0) {
   587                          priv->cache_buf = malloc(cert_len);
   588                          if (priv->cache_buf == NULL) {
   589                                  r = SC_ERROR_OUT_OF_MEMORY;
   590                                  goto done;
   591                          }
   592                          priv->cache_buf_len = cert_len;
   593                          memcpy(priv->cache_buf, cert_ptr, cert_len);
   594                  } else {
   595                          sc_log(card->ctx, "Can't read zero-length certificate");
   596                          goto done;
   597                  }
   598                  break;
   599          case CAC_OBJECT_TYPE_GENERIC:
   600                  /* TODO
   601                   * We have some two buffers in unknown encoding that we
   602                   * need to present in PKCS#15 layer.
   603                   */
   604          default:
   605                  /* Unknown object type */
   606                  sc_log(card->ctx, "Unknown object type: %x", priv->object_type);
   607                  r = SC_ERROR_INTERNAL;
   608                  goto done;
   609          }
   610
   611          /* OK we've read the data, now copy the required portion out to the callers buffer */
   612          priv->cached = 1;
   613          len = MIN(count, priv->cache_buf_len-idx);
   614          memcpy(buf, &priv->cache_buf[idx], len);
   615          r = len;
   616  done:
   617          if (tl)
   618                  free(tl);
   619          if (val)
   620                  free(val);
   621          LOG_FUNC_RETURN(card->ctx, r);
   622  }
